#include <cstddef>
#include <cstdint>
#include <memory>
#include <utility>

class Arena
{
public:
    explicit Arena(std::size_t capacity) : m_buffer{ std::make_unique<std::byte[]>(capacity) }, m_capacity{ capacity } {}

    void* allocate(std::size_t bytes, std::size_t alignment)
    {
        const auto base{ reinterpret_cast<std::uintptr_t>(m_buffer.get()) };
        const std::uintptr_t aligned{ (base + m_used + alignment - 1) & ~(static_cast<std::uintptr_t>(alignment) - 1) };
        const std::size_t offset{ static_cast<std::size_t>(aligned - base) };
        if (offset > m_capacity || bytes > m_capacity - offset)
        {
            return nullptr;
        }
        m_used = offset + bytes;
        return m_buffer.get() + offset;
    }

    template <typename T, typename... Args>
    T* create(Args&&... args)
    {
        void* memory{ allocate(sizeof(T), alignof(T)) };
        if (memory == nullptr)
        {
            return nullptr;
        }
        return std::construct_at(static_cast<T*>(memory), std::forward<Args>(args)...);
    }

    std::size_t used() const { return m_used; }
    std::size_t capacity() const { return m_capacity; }
    void reset() { m_used = 0; }

private:
    std::unique_ptr<std::byte[]> m_buffer{};
    std::size_t m_capacity{ 0 };
    std::size_t m_used{ 0 };
};

unitTests:
struct Vec3 { float x, y, z; };
bool isAligned(const void* p, std::size_t a) { return reinterpret_cast<std::uintptr_t>(p) % a == 0; }

TEST("hands out consecutive memory") { Arena a{ 64 }; CHECK_EQ(a.capacity(), 64u); void* p{ a.allocate(10, 1) }; void* q{ a.allocate(10, 1) }; CHECK(p != nullptr); CHECK(q == static_cast<std::byte*>(p) + 10); CHECK_EQ(a.used(), 20u); }
TEST("respects alignment") { Arena a{ 256 }; a.allocate(1, 1); void* p{ a.allocate(8, 8) }; CHECK(isAligned(p, 8)); a.allocate(3, 1); void* q{ a.allocate(4, 16) }; CHECK(isAligned(q, 16)); double* d{ a.create<double>(2.5) }; CHECK(isAligned(d, alignof(double))); CHECK_NEAR(*d, 2.5, 1e-12); }
TEST("returns nullptr when full, without changing anything") { Arena a{ 16 }; CHECK(a.allocate(12, 1) != nullptr); const auto before{ a.used() }; CHECK(a.allocate(5, 1) == nullptr); CHECK_EQ(a.used(), before); CHECK(a.allocate(4, 1) != nullptr); CHECK(a.allocate(1, 1) == nullptr); }
TEST("create constructs objects") { Arena a{ 1024 }; Vec3* v{ a.create<Vec3>(1.0f, 2.0f, 3.0f) }; int* n{ a.create<int>(42) }; CHECK(v != nullptr && n != nullptr); if (v && n) { CHECK_NEAR(v->y, 2.0, 1e-6); CHECK_EQ(*n, 42); } }
TEST("reset frees everything at once") { Arena a{ 32 }; void* first{ a.allocate(32, 1) }; CHECK(a.allocate(1, 1) == nullptr); a.reset(); CHECK_EQ(a.used(), 0u); CHECK(a.allocate(32, 1) == first); }
TEST("ten thousand objects, one allocation") { CHECK_NO_LEAK(Arena a{ 10000 * sizeof(Vec3) + 64 }; int made{ 0 }; while (a.create<Vec3>(0.f, 0.f, 0.f)) ++made; if (made < 10000) throw std::runtime_error{ "too few" }); }

